    nums := generate(1, 2, 3, 4, 5)
    squares := square(nums)
    for s := range squares {
        fmt.Printf("%d ", s)
    }
    fmt.Println()

    // Select
    ch1 := make(chan string)
    ch2 := make(chan string)

    go func() {
        time.Sleep(50 time.Millisecond)
        ch1 <"satu"
    }()
    go func() {
        time.Sleep(100 time.Millisecond)
        ch2 <"dua"
    }()

    select {
    case msg := <-ch1:
        fmt.Println("Dari ch1:", msg)
    case msg := <-ch2:
        fmt.Println("Dari ch2:", msg)
    case <-time.After(200 time.Millisecond):
        fmt.Println("Timeout")
    }
}
--Penjelasan

Channel adalah pipe komunikasi antar goroutine. Unbuffered: sinkron (pengirim menunggu penerima). Buffered: async sampai buffer penuh.  menunggu multiple channel. Pipeline pattern: generator → process → collector.  menandai channel selesai.

