go
package main

import (
    "context"
    "fmt"
    "sync"
    "time"
)

func doWork(ctx context.Context, id int, wg *sync.WaitGroup) {
    defer wg.Done()
    select {
    case <-time.After(200 time.Millisecond):
        fmt.Printf("Worker %d selesai\n", id)
    case <-ctx.Done():
        fmt.Printf("Worker %d dibatalkan: %v\n", id, ctx.Err())
    }
}

// Worker pool
type Pool struct {
    jobs    chan int
    results chan int
    wg      sync.WaitGroup
}

func NewPool(numWorkers int) *Pool {
    p := &Pool{
        jobs:    make(chan int, 100),
        results: make(chan int, 100),
    }
    for i := 0; i < numWorkers; i+{
        p.wg.Add(1)
        go p.worker(i)
    }
    return p
}

func (p *Pool) worker(id int) {
    defer p.wg.Done()
    for job := range p.jobs {
        p.results <job job
    }
}

func main() {
    // Context timeout
    ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
    defer cancel()

    var wg sync.WaitGroup
    for i := 1; i <= 3; i+{
        wg.Add(1)
        go doWork(ctx, i, &wg)
    }
    wg.Wait()

    // Worker pool
    fmt.Println("\nWorker Pool:")
    pool := NewPool(3)
    go func() {
        for i := 1; i <= 5; i+{
            pool.jobs <i
        }
        close(pool.jobs)
    }()

    go func() {
        pool.wg.Wait()
        close(pool.results)
    }()

    for r := range pool.results {
        fmt.Printf("Hasil: %d\n", r)
    }
}
--Penjelasan

 membawa cancellation, timeout, dan nilai. , ,  untuk kontrol.  menggabungkan error dari multiple goroutine. Worker pool membatasi concurrency. Fan-in menggabungkan channel, fan-out mendistribusikan.

