--Program: Manajemen Memori

rust
use std::rc::Rc;
use std::cell::RefCell;

struct Node {
    name: String,
    children: Vec<Rc<RefCell<Node>>>,
}

impl Node {
    fn new(name: &str) -> Rc<RefCell<Node>> {
        Rc::new(RefCell::new(Node {
            name: String::from(name),
            children: vec![],
        }))
    }

    fn add_child(parent: &Rc<RefCell<Node>>, child: Rc<RefCell<Node>>) {
        parent.borrow_mut().children.push(child);
    }
}

fn main() {
    let root = Node::new("root");
    let a = Node::new("A");
    let b = Node::new("B");

    Node::add_child(&root, a);
    Node::add_child(&root, b);

    println!("Root children count: {}", root.borrow().children.len());
    println!("Reference count root: {}", Rc::strong_count(&root));

    let data = RefCell::new(42);
    *data.borrow_mut() += 10;
    println!("RefCell value: {}", data.borrow());
}

impl Drop for Node {
    fn drop(&mut self) {
        println!("Dropping node: {}", self.name);
    }
}
Run the program on the right to see the output. This code demonstrates all concepts for this week.

--Explanation

Box<T>

 — heap allocation. Essential for recursive types and large data. The  trait allows use like regular references.

Rc<T>

 — Reference Counting for multiple ownership in single-threaded contexts.  increments the reference counter.  to check reference count.

RefCell<T>

Interior mutability: mutation through immutable references.  and  with runtime checks. Panics if borrowing rules are violated at runtime.

Drop

 trait — cleanup when a value goes out of scope.  is called automatically. Useful for resource management.

