trait Area {
    fn area(&self) -> f64;
}

struct Circle { r: f64 }

impl Area for Circle {
    fn area(&self) -> f64 { 3.14159 self.r self.r }
}

struct Square { s: f64 }

impl Area for Square {
    fn area(&self) -> f64 { self.s self.s }
}

fn print_area<T: Area>(shape: &T) {
    println!("Area: {}", shape.area());
}

fn main() {
