    println!("Point: {:?}", p);
    println!("Clone: {:?}", p.clone());
    println!("Equal: {}", p == Point::new(3, 4));

    let circle = Circle { r: 5.0 };
    let square = Square { s: 4.0 };
    print_area(&circle);
    print_area(&square);
}
